def tangency_mode():
    mode = os.environ.get("GEOSOLVER_S3_TANGENCY_MODE", "T2")
    if mode not in {"T0", "T1", "T2"}:
        raise ValueError("GEOSOLVER_S3_TANGENCY_MODE must be T0, T1 or T2")
    return mode

def distance_radius_sources(constructions, equalities):
    """Match the frozen Distance/Line/Circle syntax, without requiring contact.

    T1 uses the normalized line coefficients, not a contact point.  Resolve
    aliases exactly as distance_contact_sources does; do not infer incidence.
    """
    from geosolver.engine.standard.problem.tangency_contacts import _parse
    from geosolver.problem.expression_source import source_expression

    definitions = {name: _parse(source) for name, source in constructions}

    def resolve(node):
        seen = set()
        while isinstance(node, ast.Name) and node.id in definitions:
            if node.id in seen:
                raise ValueError("cyclic construction")
            seen.add(node.id)
            node = definitions[node.id]
        return node

    def call(node, name):
        return (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Name)
            and node.func.id == name
            and len(node.args) == 2
            and not node.keywords
        )

    def same(a, b):
        return source_expression(resolve(a)) == source_expression(resolve(b))

    result = {}
    try:
        circles = [(name, resolve(node)) for name, node in definitions.items()]
        circles = [(name, node) for name, node in circles if call(node, "Circle")]
        for index, (lhs, rhs) in enumerate(equalities):
            a, b = _parse(lhs), _parse(str(rhs))
            for distance, radius in ((resolve(a), b), (resolve(b), a)):
                if not call(distance, "Distance"):
                    continue
                for point, line in (distance.args, distance.args[::-1]):
                    if not call(resolve(line), "Line"):
                        continue
                    for name, circle in circles:
                        if not same(point, circle.args[0]) or not same(radius, circle.args[1]):
                            continue
                        line_source = f"({source_expression(line)})"
                        delta = (
                            f"({line_source}.a*Center({name}).x"
                            f"+{line_source}.b*Center({name}).y+{line_source}.c)"
                        )
                        result[index] = f"{delta}**2-Radius({name})**2"
        return result
    except (ValueError, TypeError, RecursionError):
        return {}

def _is_zero_target(target: object) -> bool:
    """Return whether the target is numerically zero."""

    if isinstance(target, str):
        return target.strip() == "0"
    try:
        return mp.mpf(target) == mp.mpf("0")
    except TimeoutError:
        raise
    except Exception:
        return False

def _zero_constraint_plans(constraints, targets):
    from geosolver.engine.standard.problem.zero_test_source import zero_test_call

    plans = {}
    for index, expression in enumerate(constraints):
        if index >= len(targets) or not _is_zero_target(targets[index]):
            continue
        node = zero_test_call(expression)
        if not isinstance(node, ast.Call) or node.keywords or len(node.args) != _BINARY_ARITY:
            continue
        if not isinstance(node.func, ast.Name):
            continue
        kind = node.func.id.lower()
        if kind in {"distance", "istangent"}:
            plans[index] = kind, tuple(ast.get_source_segment(expression, arg) for arg in node.args)
    return plans

def _run_findroot_closure(
    *,
    evaluator: EvaluatorPort,
    start_point: list[MPFloat],
    bounds: tuple[tuple[MPFloat | None, MPFloat | None], ...],
    dps: int,
    target_residual: MPFloat,
    max_steps: int,
    residual_fn: Callable[[list[MPFloat], int], list[MPFloat] | None] | None = None,
    deadline_monotonic: float | None = None,
    one_sided_at_cusp: bool = False,
    solver_tolerance: MPFloat | None = None,
) -> tuple[list[MPFloat], MPFloat] | None:
    if len(start_point) == 0:
        return None
    tolerance = target_residual if solver_tolerance is None else solver_tolerance

    def evaluate_residuals(point: list[MPFloat]) -> tuple[MPFloat, ...]:
        if deadline_monotonic is not None and time.monotonic() >= float(deadline_monotonic):
            raise _ClosureDeadlineExceeded
        if residual_fn is not None:
            with mp.workdps(int(dps)), high_precision_mode():
                values = residual_fn(point, int(dps))
            if values is None:
                raise ValueError("closure residual evaluation failed")
            return tuple(values)
        with mp.workdps(int(dps)), high_precision_mode():
            hp_eval = evaluator.evaluate_hp_residual(point, precision=int(dps))
        if hp_eval.evaluation_status is not EvaluationStatus.OK:
            raise ValueError(f"findroot residual status={hp_eval.evaluation_status.value}")
        return tuple(hp_eval.residual_vector)

    def certify(point: list[MPFloat] | None) -> tuple[list[MPFloat], MPFloat] | None:
        if deadline_monotonic is not None and time.monotonic() >= float(deadline_monotonic):
            return None
        if point is None or len(point) != len(start_point):
            return None
        if not _point_within_bounds(point, bounds):
            return None
        with mp.workdps(int(dps)), high_precision_mode():
            hp_eval = evaluator.evaluate_hp_residual(point, precision=int(dps))
        if hp_eval.evaluation_status is not EvaluationStatus.OK:
            return None
        with mp.workdps(int(dps)):
            residual_norm = _vector_norm(list(hp_eval.residual_vector))
        # ``mp.findroot`` can stop because its step became small even when the
        # residual is still far above the requested tolerance.  A rank-aware
        # chart changes only the Newton coordinates, never this certification
        # over every original source residual.
        if not mp.isfinite(residual_norm) or residual_norm > mp.mpf(target_residual):
            return None
        return point, residual_norm

    # The incoming point can retain more bits than this closure's arithmetic.
    # Keep those bits if every original residual already meets the requested
    # target. Otherwise Newton must start at its own working precision: its
    # damping loop detects stagnation by exact equality of consecutive points.
    certified_start = certify(list(start_point))
    if certified_start is not None:
        return certified_start
    with mp.workdps(int(dps)):
        start_point = [+mp.mpf(value) for value in start_point]

    try:
        initial_residuals = evaluate_residuals(list(start_point))
    except (TypeError, ValueError, ZeroDivisionError, IndexError, _ClosureDeadlineExceeded):
        return None
    standard_point: list[MPFloat] | None = None
    native_residuals = residual_fn is None or (
        isinstance(residual_fn, partial)
        and getattr(residual_fn.func, "__name__", None) == "_residual_vector_for_stage"
        and not residual_fn.keywords.get("integer_closures")
    )
    plan = derivative_plan(getattr(evaluator, "bundle", None)) if native_residuals else None
    if plan is not None and (
        plan["rows"] != len(initial_residuals)
        or (
            plan["requires_smoothing"]
            and not (
                isinstance(residual_fn, partial)
                and residual_fn.keywords.get("smooth_zero_constraints")
                and not ablated("NO_RESIDUAL_REWRITE")
                and tangency_mode() != "T0"
            )
        )
    ):
        plan = None

    def analytic_values(point):
        if deadline_monotonic is not None and time.monotonic() >= float(deadline_monotonic):
            raise _ClosureDeadlineExceeded
        with high_precision_mode():
            return evaluate_jacobian(plan, point, int(dps))

    if len(start_point) == 1:

        def evaluate_scalar_residuals(arg: MPFloat) -> tuple[MPFloat, ...]:
            return evaluate_residuals([mp.mpf(arg)])

        def scalar_residual(arg: MPFloat) -> MPFloat:
            residuals = evaluate_scalar_residuals(arg)
            if len(residuals) != 1:
                raise ValueError("scalar secant closure requires exactly one residual")
            return residuals[0]

        def overdetermined_scalar_residual(arg: MPFloat) -> tuple[MPFloat, ...]:
            return evaluate_scalar_residuals(arg)

        try:
            with mp.workdps(int(dps)):
                if len(initial_residuals) == 1:
                    root = mp.findroot(
                        scalar_residual,
                        mp.mpf(start_point[0]),
                        solver="secant",
                        tol=mp.mpf(tolerance),
                        maxsteps=int(max_steps),
                    )
                else:
                    # A one-variable problem may still have several fixed
                    # constraints.  Using residual_vector[0] here silently
                    # selected a constant constraint and made closure a no-op
                    # (or falsely accepted the unchanged point).  mpmath's
                    # multidimensional Newton path supports this overdetermined
                    # scalar case and lets the variable-dependent residual
                    # determine the root.
                    root = mp.findroot(
                        overdetermined_scalar_residual,
                        mp.mpf(start_point[0]),
                        solver="mnewton",
                        tol=mp.mpf(tolerance),
                        maxsteps=int(max_steps),
                    )
        except (TypeError, ValueError, ZeroDivisionError, IndexError, _ClosureDeadlineExceeded):
            root = None
        if root is not None:
            with mp.workdps(int(dps)):
                standard_point = _normalize_findroot_point(root)
    elif len(initial_residuals) >= len(start_point):

        def residuals(*args: MPFloat) -> tuple[MPFloat, ...]:
            point = [mp.mpf(value) for value in args]
            return evaluate_residuals(point)

        def closure_jacobian(*args):
            if deadline_monotonic is not None and time.monotonic() >= float(deadline_monotonic):
                raise _ClosureDeadlineExceeded
            values = analytic_values(list(args))
            if values is not None:
                return mp.matrix(values)
            from mpmath.calculus.optimization import jacobian

            return jacobian(mp, residuals, mp.matrix(args))

        options = {"J": closure_jacobian} if plan is not None else {}
        try:
            with mp.workdps(int(dps)):
                root = mp.findroot(
                    residuals,
                    tuple(start_point),
                    **options,
                    solver="mnewton",
                    tol=mp.mpf(tolerance),
                    maxsteps=int(max_steps),
                )
        except (TypeError, ValueError, ZeroDivisionError, IndexError, _ClosureDeadlineExceeded):
            root = None
        if root is not None:
            with mp.workdps(int(dps)):
                standard_point = _normalize_findroot_point(root)

    certified = certify(standard_point)
    if certified is not None:
        return certified

    # Underdetermined systems and square systems with a singular Jacobian are
    # closed on a local rank-revealing chart.  This is also a safe fallback
    # when full-system findroot returned a point that failed certification.
    try:
        rank_aware_point = _run_rank_aware_findroot(
            evaluate_residuals=evaluate_residuals,
            start_point=list(start_point),
            dps=int(dps),
            target_residual=tolerance,
            max_steps=int(max_steps),
            one_sided_at_cusp=bool(one_sided_at_cusp),
            derivative_fn=analytic_values if plan is not None else None,
        )
    except _ClosureDeadlineExceeded:
        return None
    return certify(rank_aware_point)

def _plan(key):
    from geosolver.runtime.symbolic import OptionalSymbolicTimeout, request

    try:
        return request("refinement_jacobian", key, timeout_seconds=1.5)
    except (
        OptionalSymbolicTimeout,
        ValueError,
        TypeError,
        ArithmeticError,
        KeyError,
        RecursionError,
    ):
        # A rejected optional plan must leave the original numerical Jacobian
        # available. The worker translates compiler errors to ValueError;
        # direct algorithm calls can retain their original exception type.
        # Ordinary TimeoutError is deliberately excluded: solve deadlines
        # still propagate to the completed-work retention path.
        return None

def _variable_scales(evaluator, values):
    plan = getattr(evaluator.bundle, "analysis_plan", None)
    bounds = (
        plan.bounds_at_precision(mp.dps)
        if plan is not None
        else infer_problem_bounds(evaluator.bundle)
    )
    return tuple(
        max(abs(mp.mpf(hi) - mp.mpf(lo)), abs(v), mp.mpf(1))
        for v, (lo, hi) in zip(values, bounds, strict=True)
    )

def _smooth_zero_equation(source):
    """Rewrite only zero-preserving outer operations, never arbitrary subterms.

    Area and abs keep their public meanings. This representation is used only
    for an equality whose complete normalized residual must be zero.
    """

    references = component_references(source)
    if references:
        for name, _, _ in references:
            source = source.replace(name, name.replace(LOGICAL_CONTEXT, SMOOTH_LOGICAL_CONTEXT, 1))
        return source

    def walk(node):
        if isinstance(node, ast.IfExp):
            return (
                f"({walk(node.body)}) if ({source_expression(node.test, source)}) "
                f"else ({walk(node.orelse)})"
            )
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.UAdd | ast.USub):
            return ("-" if isinstance(node.op, ast.USub) else "+") + "(" + walk(node.operand) + ")"
        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Mult | ast.Div):
            # The denominator is not required to be zero and must not be changed.
            left = walk(node.left)
            right = (
                walk(node.right)
                if isinstance(node.op, ast.Mult)
                else source_expression(node.right, source)
            )
            return f"({left}){'*' if isinstance(node.op, ast.Mult) else '/'}({right})"
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and not node.keywords:
            if node.func.id == "IsTangent" and len(node.args) == 2:
                arguments = ",".join(source_expression(arg, source) for arg in node.args)
                return f"_SignedTangency({arguments})"
            if node.func.id in {"abs", "Abs"} and len(node.args) == 1:
                return walk(node.args[0])
            if node.func.id == "Area" and len(node.args) == 3:
                a, b, c = (f"({source_expression(arg, source)})" for arg in node.args)
                return f"(({b}.x-{a}.x)*({c}.y-{a}.y)-({b}.y-{a}.y)*({c}.x-{a}.x))/2"
            if node.func.id == "Distance" and len(node.args) == 2:
                point, line = node.args
                if (
                    isinstance(line, ast.Call)
                    and isinstance(line.func, ast.Name)
                    and line.func.id == "Line"
                    and len(line.args) == 2
                ):
                    p, a, b = (f"({source_expression(arg, source)})" for arg in (point, *line.args))
                    # Retain the line's nondegeneracy domain. A bare cross
                    # product would silently accept coincident endpoints.
                    return (
                        f"(({b}.x-{a}.x)*({p}.y-{a}.y)-"
                        f"({b}.y-{a}.y)*({p}.x-{a}.x))/Distance({a},{b})"
                    )
            if (
                node.func.id == "min"
                and node.args
                and all(
                    isinstance(arg, ast.Call)
                    and isinstance(arg.func, ast.Name)
                    and arg.func.id in {"Distance", "abs", "Abs"}
                    for arg in node.args
                )
            ):
                result = walk(node.args[-1])
                for i in reversed(range(len(node.args) - 1)):
                    condition = " and ".join(
                        f"({source_expression(node.args[i], source)})<="
                        f"({source_expression(other, source)})"
                        for other in node.args[i + 1 :]
                    )
                    result = f"({walk(node.args[i])}) if ({condition}) else ({result})"
                return result
        return source_expression(node, source)

    return walk(ast.parse(source, mode="eval").body)

def prepare_equations(evaluator):
    from geosolver.engine.standard.evaluation.ir_evaluator import build_ir_evaluator

    equations = []
    from geosolver.runtime.symbolic import request

    problem = evaluator.bundle.spec
    ordinary = [
        (i, source)
        for i, source in enumerate(problem.constraints)
        if not component_references(source)
    ]
    leaves = tuple(dict.fromkeys(leaf for plan in problem.logical_plans for leaf in plan.leaves))
    # Normalize each equality leaf once, not the exponentially repeated source
    # of a conditional vector. Selection still uses the original residuals.
    payload = [(source, str(evaluator.bundle.targets[i])) for i, source in ordinary] + [
        (leaf, "0") for leaf in leaves
    ]
    results = request("normalize", payload) if payload else []
    normalized = {i: result for (i, _), result in zip(ordinary, results, strict=False)}
    evaluator.evaluation_store.logical_zero_sources.update(
        {
            leaf: _smooth_zero_equation(text)
            for leaf, (text, _) in zip(leaves, results[len(ordinary) :], strict=True)
        }
    )
    for index, source in enumerate(problem.constraints):
        text, constant = normalized.get(index, (source, None))
        text = _smooth_zero_equation(text)
        names = {
            name
            for leaf in evaluation_sources(text, problem.logical_plans)
            for name in extract_names(leaf)
        }
        needed = []
        for item in reversed(evaluator.bundle.spec.construction):
            if item.name in names:
                needed.append(item)
                names.update(extract_names(item.expr))
        spec = replace(
            evaluator.bundle.spec,
            construction=list(reversed(needed)),
            constraints=[text],
            v=[0],
            m=None,
        )
        bundle = replace(evaluator.bundle, spec=spec, targets=(0,))
        terms = _additive_terms(text)
        scale_evaluator = None
        if len(terms) > 1 and constant is None:
            scale_spec = replace(spec, constraints=terms, v=[0] * len(terms))
            scale_evaluator = build_ir_evaluator(
                replace(bundle, spec=scale_spec, targets=(0,) * len(terms)),
                evaluation_store=evaluator.evaluation_store,
            )
        equations.append(
            Equation(
                build_ir_evaluator(bundle, evaluation_store=evaluator.evaluation_store),
                frozenset(names),
                constant,
                text,
                scale_evaluator,
            )
        )
    return tuple(equations)

def linearization(equations, point, names, scales, precision, *, base_samples=None, batch=True):
    residuals, jacobian, errors, term_scales = [], [], [], []
    system = None
    if batch and equations and all(isinstance(e, Equation) for e in equations):
        from .verification_system import VerificationSystem

        system = VerificationSystem(equations)
    all_indices = tuple(range(len(equations)))
    columns = tuple(tuple(i for i, e in enumerate(equations) if name in e.names) for name in names)
    for i, equation in enumerate(equations):
        base = (
            system.sample(i, point, precision, all_indices)
            if system is not None
            else equation.sample(point, precision)
        )
        if base_samples is not None:
            base_samples.append(base)
        residuals.append(base[0])
        term_scales.append(max(equation.term_scale(point, precision), base[2] / mp.eps))
        row, err = [], []
        for j, name in enumerate(names):
            if name not in equation.names:
                derivative = (mp.mpf(0), mp.mpf(0))
            else:
                function = (
                    (lambda p, i=i, j=j: system.sample(i, p, precision, columns[j]))
                    if system is not None
                    else (lambda p, equation=equation: equation.sample(p, precision))
                )
                derivative = differentiate(
                    function,
                    point,
                    j,
                    scales[j],
                    precision,
                    base,
                )
            row.append(mp.mpf(0) if derivative is None else derivative[0])
            err.append(mp.inf if derivative is None else derivative[1])
        jacobian.append(row)
        errors.append(err)
        # Two arithmetic precisions can both round a cancelling primitive to
        # zero. Never infer zero coordinate error from that coincidence. The
        # locally resolved sensitivities provide a scale-covariant roundoff
        # floor, including when all explicit additive terms vanished.
        term_scales[-1] = max(
            term_scales[-1],
            mp.fsum(abs(d) * s for d, s, e in zip(row, scales, err, strict=True) if mp.isfinite(e)),
        )
    return residuals, jacobian, errors, term_scales

def correction(
    residuals, jacobian, errors, scales, precision, evaluation_scales=None, active_columns=None
):
    from geosolver.engine.standard.refinement.mpmath_refiner import _select_rank_revealing_subsystem

    row_scales = [
        max([abs(r)] + [abs(d) * s for d, s in zip(row, scales, strict=True)])
        for r, row in zip(residuals, jacobian, strict=True)
    ]
    matrix = [
        [d * s / rs if rs else mp.mpf(0) for d, s in zip(row, scales, strict=True)]
        for row, rs in zip(jacobian, row_scales, strict=True)
    ]
    reliable = []
    for i, (row, err, rs) in enumerate(zip(jacobian, errors, row_scales, strict=True)):
        signal = mp.fsum(abs(d) * s for d, s in zip(row, scales, strict=True))
        noise = mp.fsum(e * s for e, s in zip(err, scales, strict=True))
        if rs and mp.isfinite(noise) and signal > 100 * noise:
            reliable.append(i)
        else:
            matrix[i] = [mp.mpf(0)] * len(scales)
    error_bound = max(
        [mp.eps * 100]
        + [e * s / row_scales[i] for i in reliable for e, s in zip(errors[i], scales, strict=True)]
    )
    # A numerically flat redundant row must neither become an independent
    # equation nor inflate the rank tolerance of otherwise reliable rows.
    chart = _select_rank_revealing_subsystem(
        matrix, dps=precision, relative_tolerance=100 * error_bound
    )
    active = set(range(len(scales))) if active_columns is None else set(active_columns)
    unresolved = [
        _unresolved_coordinate_error(s, precision) if j in active else mp.mpf(0)
        for j, s in enumerate(scales)
    ]
    if chart is None:
        if evaluation_scales is not None and all(
            abs(r) <= mp.eps * s for r, s in zip(residuals, evaluation_scales, strict=True)
        ):
            return tuple(mp.mpf(0) for _ in scales), tuple(unresolved)
        return tuple(mp.mpf(0) for _ in scales), tuple(
            mp.inf if any(residuals) and j in active else unresolved[j] for j in range(len(scales))
        )
    rows, columns = chart
    a = mp.matrix([[matrix[i][j] for j in columns] for i in rows])
    b = mp.matrix([-residuals[i] / row_scales[i] for i in rows])
    try:
        delta = mp.lu_solve(a, b)
        inverse = a**-1
    except (ValueError, ZeroDivisionError):
        return None, None
    change = [mp.mpf(0)] * len(scales)
    uncertainty = unresolved.copy()
    unselected = active.difference(columns)
    for k, j in enumerate(columns):
        change[j] = delta[k] * scales[j]
        propagated = mp.fsum(
            abs(inverse[k, column_index])
            * (
                mp.eps
                * 32
                * (evaluation_scales[i] / row_scales[i] if evaluation_scales is not None else 1)
                + mp.fsum(
                    errors[i][c] * scales[c] / row_scales[i] * abs(delta[q])
                    for q, c in enumerate(columns)
                )
                + mp.fsum(
                    (abs(jacobian[i][c]) + errors[i][c]) * unresolved[c] / row_scales[i]
                    for c in unselected
                )
            )
            for column_index, i in enumerate(rows)
        )
        uncertainty[j] = abs(change[j]) + propagated * scales[j]
    return tuple(change), tuple(uncertainty)

def verification_equations(self):
        from geosolver.engine.standard.evaluation.verification_numerics import prepare_equations

        return prepare_equations(self)

def integer_specs(self):
        from geosolver.engine.standard.refinement.mpmath_refiner import _build_integer_specs

        return _build_integer_specs(bundle=self.bundle)

def mathematical_bounds_at_precision(self, precision):
        if precision not in self._mathematical_bounds:
            from geosolver.engine.standard.refinement.mpmath_refiner import _convert_bounds_uncached

            self._mathematical_bounds[precision] = _convert_bounds_uncached(self.bundle, precision)
        return self._mathematical_bounds[precision]

def _should_select_fallback_attempt(
    *,
    primary_outcome: _OrderedSearchAttemptOutcome,
    fallback_outcome: _OrderedSearchAttemptOutcome,
) -> bool:
    primary_result = primary_outcome.completed_stage_state
    fallback_result = fallback_outcome.completed_stage_state
    if len(fallback_result.exact_assembly_result.accepted_candidates) > len(
        primary_result.exact_assembly_result.accepted_candidates
    ):
        return True
    if len(fallback_result.exact_assembly_result.accepted_candidates) < len(
        primary_result.exact_assembly_result.accepted_candidates
    ):
        return False
    fallback_best = _best_refinement_residual(fallback_result.refinement_result)
    primary_best = _best_refinement_residual(primary_result.refinement_result)
    if fallback_best < primary_best:
        return True
    if fallback_best > primary_best:
        return False
    return (
        fallback_result.search_result.evaluation_count
        > primary_result.search_result.evaluation_count
    )

def signed_tangency(first, second):
    """Have the same absolute value/domain as IsTangent, without its zero cusp.

    The line--circle residual is |signed distance|-r; near either tangent it
    is smooth.  Unlike a squared residual, its units and conditioning remain
    those of the public distance residual.  For circles choose the nearer
    tangency equation; coincident circles must never become a zero.
    """
    from geosolver.geometry.mp.mp_api import MP_IsTangent

    # IsTangent also accepts arcs and tests their supporting circles.
    first = getattr(first, "circle", first)
    second = getattr(second, "circle", second)

    if hasattr(first, "a") and hasattr(second, "radius"):
        line, circle = first, second
    elif hasattr(second, "a") and hasattr(first, "radius"):
        line, circle = second, first
    else:
        line = circle = None
    if line is not None:
        if circle.radius <= 0:
            return MP_IsTangent(first, second)
        distance = line.a * circle.center.x + line.b * circle.center.y + line.c
        return abs(distance) - circle.radius
    if hasattr(first, "radius") and hasattr(second, "radius"):
        distance = first.center.distance_to(second.center)
        if distance == 0 or first.radius <= 0 or second.radius <= 0:
            return MP_IsTangent(first, second)
        outer = distance - (first.radius + second.radius)
        inner = distance - abs(first.radius - second.radius)
        return outer if abs(outer) <= abs(inner) else inner
    return MP_IsTangent(first, second)

def dispatch(operation, payload):
    if operation == "refinement_jacobian":
        from geosolver.engine.standard.refinement.analytic_jacobian import compile_jacobian

        return compile_jacobian(payload)
    if operation == "constant_geometry":
        from geosolver.engine.standard.exact_assembly.constant_geometry import (
            constant_geometry_expression,
        )

        return constant_geometry_expression(payload)
    if operation == "algebraic_branches":
        from geosolver.engine.standard.search.algebraic_branches import discover_polynomial_branches

        return discover_polynomial_branches(payload)
    if operation == "zero_signature":
        import sympy as sp

        from geosolver.problem.scalar_geometry import ScalarGeometry

        source, constructions = payload
        geometry = ScalarGeometry(dict(constructions), allow_opaque=True)
        try:
            expression = geometry.scalar(geometry.parse(source))
            if sp.count_ops(expression) > 300:
                return None
            # Nonzero line denominators are separately domain-checked. Abs has
            # the same zero set as its argument. Never strip additive terms.
            numerator = sp.together(expression).as_numer_denom()[0]
            if isinstance(numerator, sp.Abs):
                numerator = numerator.args[0]
            variables = sorted(numerator.free_symbols, key=str)
            if not variables:
                return "0" if numerator == 0 else None
            poly = sp.Poly(numerator, *variables)
            monic = poly.monic()
            return str(
                sp.Poly.from_dict(
                    {powers: sp.simplify(coefficient) for powers, coefficient in monic.terms()},
                    monic.gens,
                ).as_expr()
            )
        except (ValueError, TypeError, KeyError, sp.PolynomialError):
            return None
    if operation == "scalar_identity":
        import sympy as sp

        expression = sp.sympify(payload)
        if sp.count_ops(expression) > 300:
            return False
        return sp.trigsimp(sp.expand(expression)) == 0
    if operation == "normalize":
        from geosolver.engine.standard.evaluation.exact_constants import (
            exact_constant,
            normalized_difference,
        )

        result = []
        for left, right in payload:
            text = normalized_difference(left, right)
            constant = exact_constant(text)
            result.append((text, None if constant is None else (0 if constant == 0 else 1)))
        return result
    if operation != "identify":
        raise ValueError(f"unknown symbolic operation: {operation}")
    import sympy as sp

    from geosolver.engine.standard.contracts.pipeline_result import ExactIdentificationResult
    from geosolver.engine.standard.evaluation.exact_constants import exact_constant
    from geosolver.engine.standard.exact_assembly.identify_answer import _identify_answer_proposal
    from geosolver.exact.descriptors import describe_exact

    precision = int(payload["precision"])
    with mp.workdps(precision + 50):
        value = mp.make_mpf(tuple(payload["value"]))
        expression = (
            exact_constant(payload["closed_source"]) if payload.get("closed_source") else None
        )
        if expression is not None:
            try:
                descriptor = describe_exact(expression)
                result = ExactIdentificationResult(
                    "identified",
                    "closed_scalar_expression",
                    precision,
                    None,
                    None,
                    str(expression),
                    mp.mpf(0),
                    None,
                    descriptor,
                    "exact_expression",
                )
                return encode_identification(result)
            except (ValueError, NotImplementedError):
                # An exact expression outside algebraic/affine-pi is not rounded
                # into a simpler supported value by numerical reconstruction.
                return encode_identification(
                    ExactIdentificationResult(
                        "not_identified",
                        "unsupported_exact_expression",
                        precision,
                        None,
                        None,
                        None,
                        None,
                        value,
                    )
                )
        uncertainty = (
            mp.make_mpf(tuple(payload["uncertainty"]))
            if payload.get("uncertainty") is not None
            else max(1, abs(value)) * mp.power(10, -(precision - 20))
        )
        discovery_precision = precision
        if uncertainty > 0 and mp.isfinite(uncertainty):
            digits = int(mp.floor(-mp.log10(uncertainty / max(1, abs(value)))))
            discovery_precision = min(precision, digits + 10)
        if not mp.isfinite(uncertainty) or uncertainty < 0 or discovery_precision < 30:
            return encode_identification(
                ExactIdentificationResult(
                    "not_identified",
                    "insufficient_accuracy",
                    precision,
                    None,
                    None,
                    None,
                    None,
                    value,
                )
            )
        # Zero has no useful relative digits. A nonzero cancellation remainder
        # inside the independently confirmed absolute error interval must not
        # be sent to a power-of-ten/PSLQ reconstruction as a tiny nonzero root.
        # This uses the same final absolute-error test as other proposals.
        if abs(value) <= uncertainty:
            return encode_identification(
                ExactIdentificationResult(
                    "identified",
                    "zero_within_confirmed_error",
                    precision,
                    (1, 0),
                    1,
                    "0",
                    abs(value),
                    None,
                    describe_exact(sp.Integer(0)),
                )
            )
        # Every caller has independently verified this candidate's geometry.
        # Recheck the actual exact value at the new precision; overlapping
        # decimal approximations alone are never a cache key or a proof.
        matches = {}
        for encoded in payload.get("reusable_results", ()):
            prior = decode_identification(encoded)
            if prior.descriptor is None or prior.selected_exact_value is None:
                continue
            expression = sp.sympify(prior.selected_exact_value)
            root = mp.mpf(str(sp.N(expression, precision + 50)))
            root_error = abs(root) * mp.power(10, -(precision + 40))
            distance = abs(root - value)
            if distance <= uncertainty + root_error:
                matches[prior.descriptor.canonical_key()] = prior, distance
        if len(matches) == 1:
            prior, distance = next(iter(matches.values()))
            if discovery_precision >= (prior.discovery_precision_dps or prior.input_precision_dps):
                return encode_identification(
                    replace(
                        prior,
                        input_precision_dps=precision,
                        identification_method="verified_descriptor_reuse",
                        verification_residual=distance,
                        discovery_precision_dps=discovery_precision,
                    )
                )
        proposal = None
        # Geometry lowering supplies only a proposal. The original final
        # checks have run, and this path uses the same confirmed error bound.
        if payload.get("geometry_hint"):
            try:
                expression = sp.sympify(payload["geometry_hint"])
                root = mp.mpf(str(sp.N(expression, precision + 50)))
                root_error = abs(root) * mp.power(10, -(precision + 40))
                distance = abs(root - value)
                if mp.isfinite(root) and distance <= uncertainty + root_error:
                    descriptor = describe_exact(expression)
                    return encode_identification(
                        ExactIdentificationResult(
                            exact_status="identified",
                            identification_method="verified_constant_geometry",
                            input_precision_dps=precision,
                            minimal_polynomial=None,
                            polynomial_degree=None,
                            selected_exact_value=str(expression),
                            verification_residual=distance,
                            numeric_fallback_value=None,
                            descriptor=descriptor,
                            discovery_precision_dps=discovery_precision,
                        )
                    )
            except (
                ValueError,
                TypeError,
                ArithmeticError,
                NotImplementedError,
                sp.polys.polyerrors.BasePolynomialError,
            ):
                # A valid numeric hint can still lack a supported exact
                # descriptor. Optional geometry proposals must not prevent the
                # ordinary numerical reconstruction below from being attempted.
                pass
        if payload.get("prefer_affine_pi", False):
            from geosolver.engine.standard.exact_assembly.identify_answer import (
                RELAXED_TIER,
                TIER_CONFIGS,
                _identify_affine_pi_result,
            )

            possible = _identify_affine_pi_result(
                answer_hp=value,
                config=TIER_CONFIGS.get(payload["tier"], TIER_CONFIGS[RELAXED_TIER]),
                input_precision_dps=discovery_precision,
                # A pi/Angle feature may cancel in the final answer. Keep the
                # speculative prefix cheap; the existing fallback still searches
                # the full affine-pi family after algebraic reconstruction.
                rational_only=True,
            )
            if possible is not None:
                root = mp.mpf(str(sp.N(sp.sympify(possible.selected_exact_value), precision + 50)))
                root_error = abs(root) * mp.power(10, -(precision + 40))
                if mp.isfinite(uncertainty) and abs(root - value) <= uncertainty + root_error:
                    proposal = possible
        if proposal is None:
            proposal = _identify_answer_proposal(
                answer_hp=value, tier=payload["tier"], input_precision_dps=discovery_precision
            )
        proposal = replace(
            proposal, input_precision_dps=precision, discovery_precision_dps=discovery_precision
        )
        if proposal.selected_exact_value is None:
            return encode_identification(proposal)
        expression = sp.sympify(proposal.selected_exact_value)
        root = mp.mpf(str(sp.N(expression, precision + 50)))
        root_error = abs(root) * mp.power(10, -(precision + 40))
        distance = abs(root - value)
        if not mp.isfinite(uncertainty) or distance > uncertainty + root_error:
            return encode_identification(
                replace(
                    proposal,
                    exact_status="verification_failed",
                    selected_exact_value=None,
                    verification_residual=distance,
                    numeric_fallback_value=value,
                )
            )
        try:
            descriptor = describe_exact(expression, verified_polynomial=proposal.minimal_polynomial)
        except (ValueError, NotImplementedError):
            return encode_identification(
                replace(
                    proposal,
                    exact_status="not_identified",
                    selected_exact_value=None,
                    numeric_fallback_value=value,
                )
            )
        return encode_identification(
            replace(proposal, descriptor=descriptor, verification_residual=distance)
        )
